// Собирает сцену боя двух кораблей: первый встаёт слева.
const api = game.modules.get("skyplane-combat-reverse").api;
const ships = game.actors.filter((actor) => actor.type === "skyplane-combat-reverse.ship");
if (!ships.length) return ui.notifications.warn("Нет ни одного неболёта.");
const options = ships.map((ship) => `<option value="${ship.uuid}">${foundry.utils.escapeHTML(ship.name)}</option>`).join("");
if (ships.length < 2) return ui.notifications.warn("Для боя нужны два корабля.");
const pair = await foundry.applications.api.DialogV2.prompt({
  window: { title: "Начать бой" },
  content: `<div class="form-group"><label>Слева</label><select name="left">${options}</select></div>
    <div class="form-group"><label>Справа</label><select name="right">${options}</select></div>`,
  ok: { label: "Собрать сцену боя", callback: (event, button) => [button.form.elements.left.value, button.form.elements.right.value] },
  rejectClose: false
});
if (!pair) return;
if (pair[0] === pair[1]) return ui.notifications.warn("Выберите два разных корабля.");
(await api.startBattle(pair[0], pair[1]))?.view();
